import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            if (n > m) {
                int t = n;
                n = m;
                m = t;
            }
            long V = (long) n * m;

            if (V < 100) {
                int v = (int) V;
                List<Integer>[] g = new List[v];
                for (int i = 0; i < v; i++) g[i] = new ArrayList<>();
                for (int i = 0; i < v; i++) {
                    int r1 = i / m;
                    int c1 = i % m;
                    for (int dr = -3; dr <= 3; dr++) {
                        for (int dc = -3; dc <= 3; dc++) {
                            if (Math.abs(dr) + Math.abs(dc) == 3) {
                                int r2 = r1 + dr;
                                int c2 = c1 + dc;
                                if (r2 >= 0 && r2 < n && c2 >= 0 && c2 < m) {
                                    g[i].add(r2 * m + c2);
                                }
                            }
                        }
                    }
                }
                Blossom blossom = new Blossom(g);
                int pairs = blossom.maxMatching();
                out.println(pairs * 2);
            } else {
                long res;
                if (n == 1) {
                    res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
                } else {
                    res = V;
                    res -= res % 2;
                }
                out.println(res);
            }
        }

        static class Blossom {
            List<Integer>[] graph;
            int n;
            int[] match;
            int[] p;
            int[] base;
            boolean[] used;

            Blossom(List<Integer>[] graph) {
                this.graph = graph;
                n = graph.length;
                match = new int[n];
                Arrays.fill(match, -1);
                p = new int[n];
            }

            int maxMatching() {
                for (int i = 0; i < n; i++) {
                    if (match[i] == -1) {
                        int v = findPath(i);
                        while (v != -1) {
                            int pv = p[v];
                            int ppv = match[pv];
                            match[v] = pv;
                            match[pv] = v;
                            v = ppv;
                        }
                    }
                }
                int cnt = 0;
                for (int x : match) if (x != -1) cnt++;
                return cnt / 2;
            }

            int findPath(int root) {
                Arrays.fill(p, -1);
                base = new int[n];
                for (int i = 0; i < n; i++) base[i] = i;
                used = new boolean[n];
                ArrayDeque<Integer> q = new ArrayDeque<>();
                used[root] = true;
                q.add(root);

                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : graph[u]) {
                        if (base[u] == base[v] || match[u] == v) continue;
                        if (v == root || (match[v] != -1 && p[match[v]] != -1)) {
                            int curbase = lca(u, v);
                            boolean[] blossom = new boolean[n];
                            markPath(u, curbase, v, blossom);
                            markPath(v, curbase, u, blossom);
                            for (int i = 0; i < n; i++) {
                                if (blossom[base[i]]) {
                                    base[i] = curbase;
                                    if (!used[i]) {
                                        used[i] = true;
                                        q.add(i);
                                    }
                                }
                            }
                        } else if (p[v] == -1) {
                            p[v] = u;
                            if (match[v] == -1) return v;
                            int nxt = match[v];
                            used[nxt] = true;
                            q.add(nxt);
                        }
                    }
                }
                return -1;
            }

            void markPath(int u, int curbase, int child, boolean[] blossom) {
                for (; base[u] != curbase; u = p[match[u]]) {
                    blossom[base[u]] = true;
                    blossom[base[match[u]]] = true;
                    p[u] = child;
                    child = match[u];
                }
            }

            int lca(int a, int b) {
                boolean[] seen = new boolean[n];
                while (true) {
                    a = base[a];
                    seen[a] = true;
                    if (match[a] == -1) break;
                    a = p[match[a]];
                }
                while (true) {
                    b = base[b];
                    if (seen[b]) return b;
                    b = p[match[b]];
                }
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1) throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
